from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    p = draw(st.permutations(list(range(1, n + 1))))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        k = draw(st.integers(1, 10))
    elif mode == 1:
        k = draw(st.integers(1, 10**18))
    elif mode == 2:
        p = list(range(1, n + 1))  # identity: edge case
        k = draw(st.integers(1, 10**18))
    else:
        p = sorted(p, reverse=True)  # reverse sorted
        k = draw(st.integers(1, 10**18))
    return f"{n} {k}\n{' '.join(map(str, p))}\n"


