def ref(inp):
    # The operation Q_i = P_{P_i} is Q = P∘P, so after K operations the
    # result is P^(2^K). On each cycle of length L, the element at cycle
    # index j maps to cycle index (j + m) mod L, where m = 2^K mod L.
    t = inp.split()
    n, k = int(t[0]), int(t[1])
    p = [0] + [int(x) for x in t[2:2 + n]]
    res = [0] * (n + 1)
    seen = [False] * (n + 1)
    for s in range(1, n + 1):
        if seen[s]:
            continue
        cyc = []
        x = s
        while not seen[x]:
            seen[x] = True
            cyc.append(x)
            x = p[x]
        L = len(cyc)
        m = pow(2, k, L)
        for j in range(L):
            res[cyc[j]] = cyc[(j + m) % L]
    return " ".join(str(res[i]) for i in range(1, n + 1))


