    n, k = int(t[0]), int(t[1])
    p = [int(x) for x in t[2:]]
    # One operation maps P to f∘f where f(i) = P_i (0-indexed below).
    # After K operations the function is f^K, computed by repeated squaring
    # (f^(a+b) = f^a ∘ f^b, and all powers of f commute).
