from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    kind = draw(st.integers(0, 3))
    if kind == 0:
        # identity permutation (edge case: P never changes)
        p = list(range(1, n + 1))
    elif kind == 1:
        # reverse-sorted
        p = list(range(n, 0, -1))
    else:
        p = draw(st.permutations(list(range(1, n + 1))))
        p = list(p)
    k = draw(st.one_of(st.integers(1, 3), st.integers(1, 20)))
    return f"{n} {k}\n{' '.join(map(str, p))}\n"

def validate(inp):
    try:
        lines = inp.strip().split("\n")
        if len(lines) != 2:
            return False
        head = lines[0].split()
        if len(head) != 2:
            return False
        n, k = int(head[0]), int(head[1])
        p = [int(x) for x in lines[1].split()]
    except Exception:
        return False
    if not (1 <= n <= 2 * 10**5):
        return False
    if not (1 <= k <= 10**18):
        return False
    if len(p) != n:
        return False
    if sorted(p) != list(range(1, n + 1)):
        return False
    return True

def ref(inp):
    lines = inp.strip().split("\n")
    n, k = map(int, lines[0].split())
    p = [int(x) for x in lines[1].split()]
    # Direct literal simulation (only used for small K).
    for _ in range(k):
        p = [p[p[i] - 1] for i in range(n)]
